-- Every pre-existing row belongs to Oslo, confirmed by the system owner.
begin;
create function public.portal_current_club() returns uuid language plpgsql stable as $$
declare h text;
begin
 h:=nullif(current_setting('request.headers',true),'')::jsonb->>'x-portal-club';
 if h is null or h='' then return '00000000-0000-4000-8000-000000000001'::uuid;end if;
 begin return h::uuid;exception when invalid_text_representation then return null;end;
end $$;
create or replace function public.current_app_role() returns text language sql stable security definer set search_path=public as $$
 select case when a.app_role='system_admin' then 'system_admin'
 when public.portal_club_admin(public.portal_current_club()) then 'admin'
 when exists(select 1 from public.portal_club_memberships m where m.person_id=a.person_id and m.club_id=public.portal_current_club() and m.active and m.role='member') then 'readonly'
 else 'portal_user' end from public.app_users a where a.user_id=auth.uid() and a.active
$$;
create function public.portal_club_data_allowed(c uuid) returns boolean language sql stable security definer set search_path=public as $$
 select c=public.portal_current_club() and (public.is_system_admin() or public.portal_club_member(c))
$$;
grant select,insert,update,delete on public.admin_notifications to authenticated;
revoke truncate,references,trigger on public.admin_notifications from authenticated,anon;
alter table public.admin_notifications add column club_id uuid not null default '00000000-0000-4000-8000-000000000001' references public.portal_clubs;
alter table public.admin_notifications alter column club_id set default public.portal_current_club();
create index on public.admin_notifications(club_id);
create policy portal_club_boundary on public.admin_notifications as restrictive for all to authenticated using(public.portal_club_data_allowed(club_id)) with check(public.portal_club_data_allowed(club_id));
