create policy portal_club_boundary on public.sms_messages as restrictive for all to authenticated using(public.portal_club_data_allowed(club_id)) with check(public.portal_club_data_allowed(club_id));
grant select,insert,update,delete on public.sms_replies to authenticated;
revoke truncate,references,trigger on public.sms_replies from authenticated,anon;
alter table public.sms_replies add column club_id uuid not null default '00000000-0000-4000-8000-000000000001' references public.portal_clubs;
alter table public.sms_replies alter column club_id set default public.portal_current_club();
create index on public.sms_replies(club_id);
create policy portal_club_boundary on public.sms_replies as restrictive for all to authenticated using(public.portal_club_data_allowed(club_id)) with check(public.portal_club_data_allowed(club_id));
alter table public.roles drop constraint "roles_name_key";
alter table public.roles add constraint "roles_name_key" UNIQUE (club_id,name);
alter table public.groups drop constraint "groups_name_key";
alter table public.groups add constraint "groups_name_key" UNIQUE (club_id,name);
alter table public.helper_rates drop constraint "helper_rates_year_rate_type_key";
alter table public.helper_rates add constraint "helper_rates_year_rate_type_key" UNIQUE (club_id,year, rate_type);

-- Reports use the caller's row policies rather than bypassing them.
alter function public.admin_dashboard_data() security invoker;
alter function public.admin_helper_year_overview(integer) security invoker;
alter function public.my_portal_dashboard() security invoker;
revoke all on function public.portal_current_club(),public.portal_club_data_allowed(uuid) from public;
grant execute on function public.portal_current_club(),public.portal_club_data_allowed(uuid) to authenticated,service_role;
commit;
